#include "ksNativeGlobalJob.h"
#include "ksRom.h"
#include "h8s/h8s.hpp"
#include <memory>
#include <vector>
#include <tuple>
#include <iostream>
#include <stdexcept>
#include <random>
using Event=std::tuple<bool,unsigned,unsigned,uint64_t>;
void check(bool value,const char*why){if(!value)throw std::runtime_error(why);}
struct Original:H8SEmulator{using H8SEmulator::lastread;using H8SEmulator::lastwrite;using H8SEmulator::indent;};
struct Bus:H8SDevice{std::vector<Event>events;unsigned wait=0,reads=0;static bool dsp(unsigned a){return(a>=0x400000&&a<0x400010)||(a>=0x600000&&a<0x600010);}static bool watched(unsigned a){return dsp(a)||(a>=0x15000&&a<0x18000)||(a>=0x30000&&a<0x30100)||a==0xffec22||a==0xffff61||a==0xffff62;}uint8_t read(uint32_t a)override{uint8_t value=state->memory[a];if(dsp(a))value=(a&15)==4?(reads++<wait?0:7):0;if(watched(a))events.emplace_back(false,a,value,state->cycles);return value;}void write(uint32_t a,uint8_t value)override{state->memory[a]=value;if(watched(a))events.emplace_back(true,a,value,state->cycles);}};
struct IO{ks::NativeGlobalContext&context;std::vector<uint8_t>memory;std::vector<Event>events;uint64_t now=1000;unsigned wait=0,reads=0,previous=~0u;IO(ks::NativeGlobalContext&c):context(c),memory(1<<24){}
 unsigned memoryWriteClocks(unsigned at){return at<0x400000&&!(previous&1)&&at==(previous|1u)?0:3;}
 unsigned readGlobal8(unsigned a,unsigned at){auto value=memory[a];events.emplace_back(false,a,value,now+at);return value;}
 unsigned readGlobal16(unsigned a,unsigned at){auto high=readGlobal8(a,at);return(high<<8)|readGlobal8(a+1,at);}
 unsigned readGlobal32(unsigned a,unsigned at){return(readGlobal16(a,at-3)<<16)|readGlobal16(a+2,at);}
 void writeGlobal8(unsigned a,uint8_t value,unsigned at){memory[a]=value;events.emplace_back(true,a,value,now+at);previous=a;}
 void writeGlobal16(unsigned a,uint16_t value,unsigned at){writeGlobal8(a,uint8_t(value>>8),at);writeGlobal8(a+1,uint8_t(value),at);if(a==0x174a8)context.dsp.primary=value;else if(a==0x174aa)context.dsp.alternate=value;else if(a==0x159f2)context.dsp.cached=value;}
 unsigned readRoute(ks::DspRoutingTask::Read r,unsigned at){using R=ks::DspRoutingTask::Read;switch(r){case R::PrimaryOffset:return readGlobal16(0x174a8,at);case R::AlternateOffset:return readGlobal16(0x174aa,at);case R::CachedAddress:return readGlobal16(0x159f2,at);case R::VoiceA:return readGlobal8(0x17526,at);case R::VoiceB:return readGlobal8(0x174a7,at);case R::VoiceBase:return readGlobal8(0x167ba,at);}return 0;}
 void writeRoute(ks::DspRoutingTask::Write w,uint16_t value,unsigned at){writeGlobal16(w==ks::DspRoutingTask::Write::PrimaryOffset?0x174a8:w==ks::DspRoutingTask::Write::AlternateOffset?0x174aa:0x159f2,value,at);}
 unsigned readDsp(ks::NativeDspJob::Port port,unsigned off,unsigned at){unsigned value=off==4?(reads++<wait?0:7):0;events.emplace_back(false,(port==ks::NativeDspJob::Port::A?0x400000:0x600000)+off,value,now+at);return value;}
 void writeDsp(ks::NativeDspJob::Port port,unsigned off,uint8_t value,unsigned at){events.emplace_back(true,(port==ks::NativeDspJob::Port::A?0x400000:0x600000)+off,value,now+at);previous=~0u;}
 unsigned readFault(ks::DspFaultTask::Read r,unsigned at){return readGlobal8(r==ks::DspFaultTask::Read::Latch?0xffec22:0xffff62,at);}
 void writeFault(ks::DspFaultTask::Write w,uint8_t value,unsigned at){writeGlobal8(w==ks::DspFaultTask::Write::Latch?0xffec22:w==ks::DspFaultTask::Write::Data?0xffff61:0xffff62,value,at);}
};
int main(int argc,char**argv){try{if(argc!=2)return 77;ks::Rom os(argv[1]);check(os.isValid(),"ROM");auto h=std::make_unique<Original>();h->loadmem(os.data().data(),os.data().size(),0);Bus bus;h->memmap(&bus,0,1<<24);std::mt19937 rng(0x474c4f42);uint64_t cases=0,boundaries=0,interrupts=0,mutations=0;for(unsigned i=0;i<128;++i)h->interruptPriority[i]=0;h->interruptPriority[28]=6;h->memory[112]=h->memory[113]=0;h->memory[114]=1;h->memory[115]=0x70;
 for(unsigned trial=0;trial<20484;++trial){ks::NativeGlobalContext context;IO io(context);std::copy(h->memory,h->memory+(1<<24),io.memory.begin());auto set8=[&](unsigned a,unsigned value){h->memory[a]=io.memory[a]=uint8_t(value);};auto set16=[&](unsigned a,unsigned value){set8(a,value>>8);set8(a+1,value);};auto set32=[&](unsigned a,unsigned value){set16(a,value>>16);set16(a+2,value);};unsigned part=trial&3;set8(0x17526,part);set8(0x167ba,(trial>>2)&3);set8(0x174a7,trial&15);set32(0x174ae +part*20,0x30000);for(unsigned i=0;i<256;++i){set8(0x30000+i,rng());set8(0x168fc+i,rng());}set8(0x30000+95,trial&1?0:trial>>1);set8(0x30000+113,trial&2?0:trial>>2);set8(0x30000+103,trial&4?0:trial>>3);set8(0x30000+119,trial&8?0:trial>>4);set16(0x1512e,trial%257?uint16_t(rng()):0);set16(0x15132,rng());set16(0x174a8,0);set16(0x174aa,0);set16(0x159f2,0xffff);set8(0xffec22,0);set8(0xffff62,0);context.dsp.part=uint8_t(part);context.dsp.basePart=h->memory[0x167ba];context.dsp.voiceB=h->memory[0x174a7];io.wait=bus.wait=trial>=20480?65537:trial&7;bus.reads=0;
  for(unsigned i=0;i<8;++i)h->regs[i].er=int32_t(rng());h->setSP(0xa18000);h->pushPC(h->makepc(0x4338));h->pc=h->makepc(0x96d6);h->cycles=1000;h->lastread=h->lastwrite=-1;h->ccr=uint8_t(trial);h->exr=0;h->indent=0;h->interruptMode2=true;h->pending_irqs=h->pending_irqs_high=0;ks::NativeGlobalJob job(context);unsigned count=0;
  while(!job.complete()){bus.events.clear();io.events.clear();if(trial&32){unsigned field=(count*37)&255;uint8_t value=uint8_t(trial+count*19);h->memory[0x30000+field]=io.memory[0x30000+field]=value;h->memory[0x168fc+field]=io.memory[0x168fc+field]=value;++mutations;}if(trial>=16384&&trial<20480&&count==trial-16384){h->pending_irqs=1ull<<28;h->step();io.now+=51;io.previous=~0u;check(h->cycles==io.now&&bus.events.empty(),"global IRQ pause");++interrupts;++count;++boundaries;continue;}unsigned cost=job.nextClocks(io);check(cost,"native global zero cost");check(!job.advanceBefore(cost-1,io).clocks&&io.events.empty(),"early global IO");auto progress=job.advanceBefore(cost,io);h->step();io.now+=progress.clocks;if(h->cycles!=io.now||bus.events!=io.events){std::cerr<<"trial="<<trial<<" boundary="<<count<<" original next="<<std::hex<<h->getPC()<<std::dec<<" clocks="<<h->cycles<<'/'<<io.now<<" events="<<bus.events.size()<<'/'<<io.events.size()<<'\n';for(auto e:bus.events){auto[w,a,v,t]=e;std::cerr<<"H "<<w<<' '<<std::hex<<a<<' '<<v<<std::dec<<' '<<t<<'\n';}for(auto e:io.events){auto[w,a,v,t]=e;std::cerr<<"N "<<w<<' '<<std::hex<<a<<' '<<v<<std::dec<<' '<<t<<'\n';}throw std::runtime_error("native global original timeline/events differ");}check(progress.completed==job.complete(),"global completion escaped");++boundaries;check(++count<1000000,"global stalled");}
  check(h->getPC()==0x4338,"global caller return");for(unsigned a=0x15000;a<0x18000;++a)check(h->memory[a]==io.memory[a],"global final data differs");check(bus.reads==io.reads,"global DSP status count");++cases;
 }
 std::cout<<"PASS: "<<cases<<" native complete global graphs / "<<boundaries<<" original H8 boundaries / "<<interrupts<<" IRQ pauses / "<<mutations<<" live mutations, exact typed data/MMIO/clocks\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
